"""
Test the operations on strings.

The operations follow the Python implementation, since Python is
the language of the meta-model specifications. Hence, they work on
the characters (code points) of the strings. The other SDKs test against
the very same cases.
"""


# This code has been automatically generated by aas-core-codegen.
# Do NOT edit or append.


import unittest


class Test_string_helpers(unittest.TestCase):
    def test_len_empty_text(self) -> None:
        self.assertEqual(
            0,
            len('')
        )

    def test_len_ascii_text(self) -> None:
        self.assertEqual(
            3,
            len('abc')
        )

    def test_len_character_of_two_utf_8_bytes(self) -> None:
        self.assertEqual(
            2,
            len('é-')
        )

    def test_len_character_beyond_the_basic_multilingual_plane(self) -> None:
        self.assertEqual(
            2,
            len('😀-')
        )

    def test_len_mixed_characters(self) -> None:
        self.assertEqual(
            5,
            len('aé😀b😀')
        )


if __name__ == "__main__":
    unittest.main()


